#!/usr/bin/env python3
"""Verify owner-pinned bundle, platform and installed live TCB exact sets."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import stat
from pathlib import Path


PACKAGE = Path(__file__).resolve().parents[1]


def sha(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def check_file(path: Path, expected: dict, label: str) -> None:
    if not path.is_file() or path.is_symlink():
        raise SystemExit(f"{label}: missing/non-regular file: {path}")
    if path.stat().st_size != expected["bytes"] or sha(path) != expected["sha256"]:
        raise SystemExit(f"{label}: hash/size mismatch: {path}")


def verify_platform(path: Path) -> None:
    manifest = json.loads(path.read_text(encoding="utf-8"))
    expected = {item["path"]: item for item in manifest["entries"]}
    actual_paths: set[str] = set()
    for raw in manifest["exact_set_roots"]:
        root = Path(raw)
        for parent, directories, files in os.walk(root, followlinks=False):
            directories.sort()
            files.sort()
            for name in files:
                actual_paths.add(str(Path(parent) / name))
            for name in directories:
                candidate = Path(parent) / name
                if candidate.is_symlink():
                    actual_paths.add(str(candidate))
    for item in manifest["entries"]:
        actual_paths.add(item["path"])
    if actual_paths != set(expected):
        raise SystemExit(
            "platform exact-set mismatch: "
            f"extra={sorted(actual_paths-set(expected))[:5]} "
            f"missing={sorted(set(expected)-actual_paths)[:5]}"
        )
    for raw, item in expected.items():
        path_obj = Path(raw)
        if item["kind"] == "symlink":
            if not path_obj.is_symlink() or os.readlink(path_obj) != item["target"]:
                raise SystemExit(f"platform symlink mismatch: {raw}")
        else:
            check_file(path_obj, item, "platform")
        mode = format(stat.S_IMODE(path_obj.lstat().st_mode), "04o")
        if mode != item["mode"]:
            raise SystemExit(f"platform mode mismatch: {raw}: {mode}")


def expected_live(manifest: dict) -> dict[str, dict]:
    values = {item["live_path"]: item for item in manifest["bundle_members"]}
    dependency = json.loads(
        (PACKAGE / manifest["dependency_manifest_path"]).read_text(encoding="utf-8")
    )
    for item in dependency["apsw_wheel"]["members"]:
        values["/opt/p5/authority-runtime/site-packages/" + item["path"]] = item
    return values


def verify_exact_roots(manifest: dict, expected: dict[str, dict]) -> None:
    actual: set[str] = set()
    for raw in manifest["live_exact_set_roots"]:
        root = Path(raw)
        if not root.is_dir() or root.is_symlink():
            raise SystemExit(f"live TCB root missing/symlink: {root}")
        for path in root.rglob("*"):
            if path.is_file() or path.is_symlink():
                actual.add(str(path))
    wanted = {
        path for path in expected
        if any(path == root or path.startswith(root + "/")
               for root in manifest["live_exact_set_roots"])
    }
    if actual != wanted:
        raise SystemExit(
            "live exact-set mismatch: "
            f"extra={sorted(actual-wanted)[:10]} missing={sorted(wanted-actual)[:10]}"
        )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--manifest", required=True)
    parser.add_argument("--mode", choices=("bundle", "live", "pre-reload"), required=True)
    args = parser.parse_args()
    manifest_path = Path(args.manifest)
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    dependency_path = PACKAGE / manifest["dependency_manifest_path"]
    platform_path = PACKAGE / manifest["platform_manifest_path"]
    if sha(dependency_path) != manifest["dependency_manifest_sha256"]:
        raise SystemExit("dependency manifest hash mismatch")
    if sha(platform_path) != manifest["platform_manifest_sha256"]:
        raise SystemExit("platform manifest hash mismatch")
    verify_platform(platform_path)
    if args.mode == "bundle":
        observed = set()
        for item in manifest["bundle_members"]:
            path = PACKAGE / item["bundle_path"]
            check_file(path, item, "bundle")
            observed.add(item["bundle_path"])
        actual = {
            path.relative_to(PACKAGE).as_posix()
            for path in (PACKAGE / "tcb" / "bundle").rglob("*") if path.is_file()
        }
        if observed != actual:
            raise SystemExit("bundle exact-set mismatch")
    else:
        expected = expected_live(manifest)
        selected = (
            set(manifest["daemon_reload_gate"]["required_before_daemon_reload"])
            if args.mode == "pre-reload" else set(expected)
        )
        for raw in sorted(selected):
            check_file(Path(raw), expected[raw], "live")
        if args.mode == "live":
            verify_exact_roots(manifest, expected)
    print(f"TCB_{args.mode.upper().replace('-', '_')}=PASS")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
